// Auto-generated: base64-encoded "SKUs_with_variance_for_RFQ.xlsx" RFQ data pack.
// Linked to the Download button in the final Spend Intelligence chat message.
export const RFQ_DATA_PACK_FILENAME = 'SKUs_with_variance_for_RFQ.xlsx';
export const RFQ_DATA_PACK_BASE64 =
  '';

const XLSX_MIME =
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

/** Triggers a browser download of the embedded RFQ data pack xlsx. */
export function downloadRfqDataPack() {
  const byteChars = atob(RFQ_DATA_PACK_BASE64);
  const bytes = new Uint8Array(byteChars.length);
  for (let i = 0; i < byteChars.length; i++) bytes[i] = byteChars.charCodeAt(i);
  const blob = new Blob([bytes], { type: XLSX_MIME });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = RFQ_DATA_PACK_FILENAME;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}
